import { randomUUID } from "node:crypto";
const DEFAULT_LOCK_TTL_MS = 30_000;
const live = (e) => !!e && (e.expiresAt === undefined || Date.now() <= e.expiresAt);
export class MemoryStore {
    kvMap = new Map();
    lists = new Map();
    locks = new Map();
    queues = new Map();
    kv = {
        get: async (key) => {
            const e = this.kvMap.get(key);
            if (!live(e)) {
                this.kvMap.delete(key);
                return undefined;
            }
            return e.value;
        },
        set: async (key, value, ttlMs) => {
            this.kvMap.set(key, {
                value,
                expiresAt: ttlMs ? Date.now() + ttlMs : undefined,
            });
        },
        delete: async (key) => {
            this.kvMap.delete(key);
        },
        consume: async (key) => {
            const e = this.kvMap.get(key);
            if (!live(e)) {
                this.kvMap.delete(key);
                return undefined;
            }
            this.kvMap.delete(key);
            return e.value;
        },
    };
    list = {
        append: async (key, value, opts) => {
            const e = this.lists.get(key);
            const arr = live(e) ? e.value : [];
            arr.push(value);
            if (opts?.maxLen && arr.length > opts.maxLen)
                arr.splice(0, arr.length - opts.maxLen);
            this.lists.set(key, {
                value: arr,
                expiresAt: opts?.ttlMs ? Date.now() + opts.ttlMs : e?.expiresAt,
            });
            return arr.length;
        },
        range: async (key, start = 0, stop) => {
            const e = this.lists.get(key);
            if (!live(e)) {
                this.lists.delete(key);
                return [];
            }
            const arr = e.value;
            return arr.slice(start, stop === undefined ? undefined : stop + 1);
        },
        trim: async (key, maxLen) => {
            const e = this.lists.get(key);
            if (!live(e))
                return;
            const arr = e.value;
            if (arr.length > maxLen)
                arr.splice(0, arr.length - maxLen);
        },
        delete: async (key) => {
            this.lists.delete(key);
        },
    };
    lock = {
        acquire: async (key, opts) => {
            const cur = this.locks.get(key);
            if (cur && (cur.expiresAt === undefined || Date.now() <= cur.expiresAt))
                return null;
            const token = randomUUID();
            this.locks.set(key, {
                token,
                expiresAt: Date.now() + (opts?.ttlMs ?? DEFAULT_LOCK_TTL_MS),
            });
            return { token };
        },
        release: async (key, token) => {
            const cur = this.locks.get(key);
            if (cur?.token === token)
                this.locks.delete(key);
        },
    };
    dedup = {
        seen: async (key, ttlMs) => {
            const k = `dedup:${key}`;
            const e = this.kvMap.get(k);
            if (live(e))
                return true;
            this.kvMap.set(k, { value: 1, expiresAt: Date.now() + ttlMs });
            return false;
        },
    };
    queue = {
        enqueue: async (key, value, opts) => {
            const arr = this.queues.get(key) ?? [];
            if (opts?.maxSize && arr.length >= opts.maxSize) {
                if ((opts.onFull ?? "drop-oldest") === "drop-newest") {
                    this.queues.set(key, arr);
                    return arr.length;
                }
                arr.shift();
            }
            arr.push(value);
            this.queues.set(key, arr);
            return arr.length;
        },
        dequeue: async (key) => {
            const arr = this.queues.get(key);
            return arr && arr.length ? arr.shift() : undefined;
        },
        depth: async (key) => this.queues.get(key)?.length ?? 0,
    };
}
